        push_binding(
            &mut bindings,
            ":cluster",
            "Cluster current view (following/mentions/search/bookmarks)",
        );
        push_binding(
            &mut bindings,
            ":topics",
            "Regenerate cluster topic labels via LLM",
        );
        push_binding(&mut bindings, ":refresh", "Refresh current view");
        push_binding(&mut bindings, ":quit", "Quit");

