/// Build one or more `Line`s for a single binding, hanging-indenting any
/// wrapped continuation rows so they align under the description column.
fn binding_lines(
    key: &str,
    desc: &str,
    key_style: Style,
    desc_style: Style,
    desc_width: usize,
) -> Vec<Line<'static>> {
    let chunks = wrap_text(desc, desc_width);
    let mut lines = Vec::with_capacity(chunks.len().max(1));

    let mut iter = chunks.into_iter();
    let first = iter.next().unwrap_or_default();
    lines.push(Line::from(vec![
        Span::styled(format!("{:indent$}{:<width$}", "", key, indent = KEY_INDENT, width = KEY_WIDTH), key_style),
        Span::styled(first, desc_style),
    ]));
    for chunk in iter {
        lines.push(Line::from(vec![
            Span::raw(" ".repeat(DESC_COL)),
            Span::styled(chunk, desc_style),
        ]));
    }
    lines
}

/// Greedy word-wrap that respects terminal display width (CJK-aware).
///
/// Returns chunks each having `UnicodeWidthStr::width(chunk) <= max_cols`.
/// Always returns at least one chunk (an empty string for empty input).
///
/// TODO(implement): pack as many whitespace-separated tokens as fit per
/// line, using `unicode_width::UnicodeWidthChar::width` to measure each
/// character (CJK = 2 cols, control = 0). When a single token is wider
/// than `max_cols`, hard-break it by accumulating chars until the next
/// one would overflow — do NOT append an ellipsis (this is wrap, not
/// truncate; that's `ui::text::truncate_for_width`'s job).
///
/// Why this matters here: help descriptions are mostly ASCII today, but
/// the rest of the codebase already handles CJK widths correctly (see
/// `ui::text::truncate_for_width`), and the cluster/topic flow can show
/// LLM-generated topic labels containing CJK or emoji elsewhere — keeping
/// width handling consistent avoids surprise overflow when the help text
/// grows.
fn wrap_text(_text: &str, _max_cols: usize) -> Vec<String> {
    todo!("implement greedy word-wrap with CJK-aware width — see doc comment above")
}

