131	/// Build one or more `Line`s for a single binding, hanging-indenting any
132	/// wrapped continuation rows so they align under the description column.
133	fn binding_lines(
134	    key: &str,
135	    desc: &str,
136	    key_style: Style,
137	    desc_style: Style,
138	    desc_width: usize,
139	) -> Vec<Line<'static>> {
140	    let chunks = wrap_text(desc, desc_width);
141	    let mut lines = Vec::with_capacity(chunks.len().max(1));
142	
143	    let mut iter = chunks.into_iter();
144	    let first = iter.next().unwrap_or_default();
145	    lines.push(Line::from(vec![
146	        Span::styled(
147	            format!(
148	                "{:indent$}{:<width$}",
149	                "",
150	                key,
151	                indent = KEY_INDENT,
152	                width = KEY_WIDTH
153	            ),
154	            key_style,
155	        ),
156	        Span::styled(first, desc_style),
157	    ]));
158	    for chunk in iter {
159	        lines.push(Line::from(vec![
160	            Span::raw(" ".repeat(DESC_COL)),
161	            Span::styled(chunk, desc_style),
162	        ]));
163	    }
164	    lines
165	}
